import os, re, json

d = os.environ['RLM_SESSION_DIR']
session_file = f'{d}/../../sessions/{os.path.basename(d)}.jsonl'

with open(session_file, 'r') as f:
    lines = f.readlines()

# Parse each line as JSON
messages = []
for line in lines:
    try:
        messages.append(json.loads(line.strip()))
    except:
        pass

# Find test input grid in the messages
for msg in messages:
    content = msg.get('content', '')
    if isinstance(content, str):
        # Check for grid data in string content
        if content.count('[') > 5 and content.count(']') > 5:
            print("Found potential grid in message")
            print(f"Message type: {msg.get('type')}")
            print(f"First 1000 chars: {content[:1000]}")
    elif isinstance(content, list):
        for item in content:
            if isinstance(item, dict):
                t = item.get('type', '')
                text = item.get('text', '')
                if t == 'thinking' and '[' in text and ']' in text:
                    print(f"\nThinking content in message: {t}")
                    print(text[:200])

print(f"\nTotal messages: {len(messages)}")

